async () => {
  const select0 = document.getElementById('selector-0');
  const select1 = document.getElementById('selector-1');

  // Set first selector to AirPods (3rd generation) with Lightning Charging Case
  const opt0 = select0.querySelector('option[value="ZEs_UZM5"]');
  if (opt0) {
    select0.value = 'ZEs_UZM5';
    select0.dispatchEvent(new Event('change', {bubbles: true}));
  }

  await new Promise(r => setTimeout(r, 500));

  // Set second selector to AirPods (3rd generation) with MagSafe Charging Case
  const opt1 = select1.querySelector('option[value="9FGnsPAg"]');
  if (opt1) {
    select1.value = '9FGnsPAg';
    select1.dispatchEvent(new Event('change', {bubbles: true}));
  }

  await new Promise(r => setTimeout(r, 1000));

  return 'Selectors updated';
}

async () => {
  // Find all three select elements
  const selects = document.querySelectorAll('select');
  console.log('Number of selects:', selects.length);

  // Check current values
  const values = Array.from(selects).map(s => s.value);
  console.log('Current values:', values);

  // Find option values for AirPods 3rd gen
  const options = Array.from(selects[0].options).map(o => ({value: o.value, text: o.text}));
  console.log('Options:', JSON.stringify(options));

  // Select AirPods (3rd generation) with Lightning Charging Case in first dropdown
  selects[0].value = 'ZEs_UZM5';
  selects[0].dispatchEvent(new Event('change', {bubbles: true}));

  await new Promise(r => setTimeout(r, 500));

  // Select AirPods (3rd generation) with MagSafe Charging Case in second dropdown
  selects[1].value = '9FGnsPAg';
  selects[1].dispatchEvent(new Event('change', {bubbles: true}));

  await new Promise(r => setTimeout(r, 1500));

  return 'Updated';
}
